  15→func TestComputeFilesHash_Deterministic(t *testing.T) {
  16→	t.Parallel()
  17→
  18→	files := []string{"b.go", "a.go", "c.go"}
  19→	hash1 := computeFilesHash(files)
  20→	hash2 := computeFilesHash(files)
  21→
  22→	if hash1 != hash2 {
  23→		t.Errorf("expected deterministic hash, got %s and %s", hash1, hash2)
  24→	}
  25→
  26→	// Order shouldn't matter
  27→	files2 := []string{"c.go", "a.go", "b.go"}
  28→	hash3 := computeFilesHash(files2)
  29→
  30→	if hash1 != hash3 {
  31→		t.Errorf("expected order-independent hash, got %s and %s", hash1, hash3)
  32→	}
  33→}
