  55→func TestWingmanPayload_RoundTrip(t *testing.T) {
  56→	t.Parallel()
  57→
  58→	payload := WingmanPayload{
  59→		SessionID:     "test-session-123",
  60→		RepoRoot:      "/tmp/repo",
  61→		BaseCommit:    "abc123def456",
  62→		ModifiedFiles: []string{"main.go", "util.go"},
  63→		NewFiles:      []string{"new.go"},
  64→		DeletedFiles:  []string{"old.go"},
  65→		Prompts:       []string{"Fix the bug", "Add tests"},
  66→		CommitMessage: "fix: resolve issue",
  67→	}
  68→
  69→	data, err := json.Marshal(payload)
  70→	if err != nil {
  71→		t.Fatalf("failed to marshal: %v", err)
  72→	}
  73→
  74→	var decoded WingmanPayload
  75→	if err := json.Unmarshal(data, &decoded); err != nil {
  76→		t.Fatalf("failed to unmarshal: %v", err)
  77→	}
  78→
  79→	if decoded.SessionID != payload.SessionID {
  80→		t.Errorf("session_id: got %q, want %q", decoded.SessionID, payload.SessionID)
  81→	}
  82→	if decoded.RepoRoot != payload.RepoRoot {
  83→		t.Errorf("repo_root: got %q, want %q", decoded.RepoRoot, payload.RepoRoot)
  84→	}
  85→	if decoded.BaseCommit != payload.BaseCommit {
  86→		t.Errorf("base_commit: got %q, want %q", decoded.BaseCommit, payload.BaseCommit)
  87→	}
  88→	if len(decoded.ModifiedFiles) != len(payload.ModifiedFiles) {
  89→		t.Errorf("modified_files: got %d, want %d", len(decoded.ModifiedFiles), len(payload.ModifiedFiles))
  90→	}
  91→	if len(decoded.NewFiles) != len(payload.NewFiles) {
  92→		t.Errorf("new_files: got %d, want %d", len(decoded.NewFiles), len(payload.NewFiles))
  93→	}
  94→	if len(decoded.DeletedFiles) != len(payload.DeletedFiles) {
  95→		t.Errorf("deleted_files: got %d, want %d", len(decoded.DeletedFiles), len(payload.DeletedFiles))
  96→	}
  97→	if len(decoded.Prompts) != len(payload.Prompts) {
  98→		t.Errorf("prompts: got %d, want %d", len(decoded.Prompts), len(payload.Prompts))
  99→	}
 100→	if decoded.CommitMessage != payload.CommitMessage {
 101→		t.Errorf("commit_message: got %q, want %q", decoded.CommitMessage, payload.CommitMessage)
 102→	}
 103→}
