 105→func TestBuildReviewPrompt_IncludesAllSections(t *testing.T) {
 106→	t.Parallel()
 107→
 108→	prompts := []string{"Fix the authentication bug"}
 109→	fileList := "auth.go (modified), auth_test.go (new)"
 110→	diff := `diff --git a/auth.go b/auth.go
 111→--- a/auth.go
 112→+++ b/auth.go
 113→@@ -10,6 +10,8 @@ func Login(user, pass string) error {
 114→+    if user == "" {
 115→+        return errors.New("empty user")
 116→+    }
 117→`
 118→
 119→	commitMsg := "Fix empty user login crash"
 120→	sessionCtx := "## Summary\nFixed authentication bug for empty usernames"
 121→
 122→	result := buildReviewPrompt(prompts, commitMsg, sessionCtx, "test-session-456", fileList, diff)
 123→
 124→	if !strings.Contains(result, "Fix the authentication bug") {
 125→		t.Error("prompt should contain user prompt")
 126→	}
 127→	if !strings.Contains(result, "auth.go (modified)") {
 128→		t.Error("prompt should contain file list")
 129→	}
 130→	if !strings.Contains(result, "diff --git") {
 131→		t.Error("prompt should contain diff")
 132→	}
 133→	if !strings.Contains(result, "intent-aware review") {
 134→		t.Error("prompt should contain reviewer instruction")
 135→	}
 136→	if !strings.Contains(result, "Fix empty user login crash") {
 137→		t.Error("prompt should contain commit message")
 138→	}
 139→	if !strings.Contains(result, "Fixed authentication bug") {
 140→		t.Error("prompt should contain session context")
 141→	}
 142→	if !strings.Contains(result, ".entire/metadata/test-session-456/full.jsonl") {
 143→		t.Error("prompt should contain checkpoint transcript path")
 144→	}
 145→	if !strings.Contains(result, ".entire/metadata/test-session-456/prompt.txt") {
 146→		t.Error("prompt should contain checkpoint prompt path")
 147→	}
 148→	if !strings.Contains(result, ".entire/metadata/test-session-456/context.md") {
 149→		t.Error("prompt should contain checkpoint context path")
 150→	}
 151→}
