 186→func TestWingmanState_SaveLoad(t *testing.T) {
 187→	// Uses t.Chdir so cannot be parallel
 188→	tmpDir := t.TempDir()
 189→
 190→	// Initialize a real git repo (paths.AbsPath needs git rev-parse)
 191→	cmd := exec.CommandContext(context.Background(), "git", "init", tmpDir)
 192→	if err := cmd.Run(); err != nil {
 193→		t.Fatalf("failed to git init: %v", err)
 194→	}
 195→
 196→	// Create .entire directory
 197→	entireDir := filepath.Join(tmpDir, ".entire")
 198→	if err := os.MkdirAll(entireDir, 0o755); err != nil {
 199→		t.Fatalf("failed to create .entire directory: %v", err)
 200→	}
 201→
 202→	t.Chdir(tmpDir)
 203→
 204→	state := &WingmanState{
 205→		SessionID:     "test-session",
 206→		FilesHash:     "abc123",
 207→		ReviewApplied: false,
 208→	}
 209→
 210→	if err := saveWingmanState(state); err != nil {
 211→		t.Fatalf("failed to save state: %v", err)
 212→	}
 213→
 214→	loaded, err := loadWingmanState()
 215→	if err != nil {
 216→		t.Fatalf("failed to load state: %v", err)
 217→	}
 218→
 219→	if loaded.SessionID != state.SessionID {
 220→		t.Errorf("session_id: got %q, want %q", loaded.SessionID, state.SessionID)
 221→	}
 222→	if loaded.FilesHash != state.FilesHash {
 223→		t.Errorf("files_hash: got %q, want %q", loaded.FilesHash, state.FilesHash)
 224→	}
 225→	if loaded.ReviewApplied != state.ReviewApplied {
 226→		t.Errorf("review_applied: got %v, want %v", loaded.ReviewApplied, state.ReviewApplied)
 227→	}
 228→}
