 254→func TestIsWingmanEnabled_Settings(t *testing.T) {
 255→	t.Parallel()
 256→
 257→	tests := []struct {
 258→		name     string
 259→		options  map[string]any
 260→		expected bool
 261→	}{
 262→		{
 263→			name:     "nil options",
 264→			options:  nil,
 265→			expected: false,
 266→		},
 267→		{
 268→			name:     "empty options",
 269→			options:  map[string]any{},
 270→			expected: false,
 271→		},
 272→		{
 273→			name:     "wingman not present",
 274→			options:  map[string]any{"summarize": map[string]any{"enabled": true}},
 275→			expected: false,
 276→		},
 277→		{
 278→			name:     "wingman enabled",
 279→			options:  map[string]any{"wingman": map[string]any{"enabled": true}},
 280→			expected: true,
 281→		},
 282→		{
 283→			name:     "wingman disabled",
 284→			options:  map[string]any{"wingman": map[string]any{"enabled": false}},
 285→			expected: false,
 286→		},
 287→		{
 288→			name:     "wingman wrong type",
 289→			options:  map[string]any{"wingman": "invalid"},
 290→			expected: false,
 291→		},
 292→		{
 293→			name:     "wingman enabled wrong type",
 294→			options:  map[string]any{"wingman": map[string]any{"enabled": "yes"}},
 295→			expected: false,
 296→		},
 297→	}
