package cli

import (
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

// WingmanAgentDef describes a CLI agent that can perform wingman reviews.
type WingmanAgentDef struct {
	Name            string
	Binary          string
	Models          []string // display order
	DefaultModel    string
	BuildReviewArgs func(model string) []string
	BuildApplyArgs  func() []string
}

// wingmanAgents is the registry of supported wingman agents.
var wingmanAgents = []WingmanAgentDef{
	{
		Name:         "claude-code",
		Binary:       "claude",
		Models:       []string{"haiku", "sonnet", "opus"},
		DefaultModel: wingmanReviewModel, // "sonnet"
		BuildReviewArgs: func(model string) []string {
			return []string{
				"--print",
				"--output-format", "json",
				"--model", model,
				"--setting-sources", "",
				"--allowedTools", "Read,Glob,Grep",
				"--permission-mode", "bypassPermissions",
			}
		},
		BuildApplyArgs: func() []string {
			return []string{
				"--continue",
				"--print",
				"--setting-sources", "",
				"--permission-mode", "acceptEdits",
			}
		},
	},
	{
		Name:         "codex",
		Binary:       "codex",
		Models:       []string{"o3-mini", "o3", "o4-mini"},
		DefaultModel: "o3",
		BuildReviewArgs: func(model string) []string {
			return []string{
				"--model", model,
				"--quiet",
				"--approval-mode", "suggest",
			}
		},
		BuildApplyArgs: func() []string {
			return []string{
				"--quiet",
				"--approval-mode", "auto-edit",
			}
		},
	},
	{
		Name:         "gemini-cli",
		Binary:       "gemini",
		Models:       []string{"flash", "pro"},
		DefaultModel: "flash",
		BuildReviewArgs: func(model string) []string {
			return []string{
				"--model", model,
			}
		},
		BuildApplyArgs: func() []string {
			return []string{
				"--sandbox",
			}
		},
	},
}

// getWingmanAgentDef returns the agent definition by name, or nil if unknown.
func getWingmanAgentDef(name string) *WingmanAgentDef {
	for i := range wingmanAgents {
		if wingmanAgents[i].Name == name {
			return &wingmanAgents[i]
		}
	}
	return nil
}

// isValidWingmanModel checks if model is valid for the given agent definition.
func isValidWingmanModel(def *WingmanAgentDef, model string) bool {
	for _, m := range def.Models {
		if m == model {
			return true
		}
	}
	return false
}

// defaultWingmanAgentName is the agent used when none is configured.
const defaultWingmanAgentName = "claude-code"

// resolveWingmanAgent resolves the active agent definition and model from settings.
// Returns the default agent (claude-code/sonnet) if nothing is configured.
func resolveWingmanAgent(s *settings.EntireSettings) (*WingmanAgentDef, string) {
	agentName := s.GetWingmanAgent()
	if agentName == "" {
		agentName = defaultWingmanAgentName
	}

	def := getWingmanAgentDef(agentName)
	if def == nil {
		// Unknown agent in settings — fall back to default
		def = getWingmanAgentDef(defaultWingmanAgentName)
	}

	model := s.GetWingmanModel()
	if model == "" || !isValidWingmanModel(def, model) {
		model = def.DefaultModel
	}

	return def, model
}

