// updateWingmanOpts merges updates into the wingman options map without
// overwriting unrelated keys (e.g., setting enabled=true preserves agent/model).
func updateWingmanOpts(s *settings.EntireSettings, updates map[string]any) {
	if s.StrategyOptions == nil {
		s.StrategyOptions = make(map[string]any)
	}
	existing, _ := s.StrategyOptions["wingman"].(map[string]any)
	if existing == nil {
		existing = make(map[string]any)
	}
	for k, v := range updates {
		existing[k] = v
	}
	s.StrategyOptions["wingman"] = existing
}

