func newWingmanAgentCmd() *cobra.Command {
	var useLocal bool

	cmd := &cobra.Command{
		Use:   "agent [name] [model]",
		Short: "List or set the wingman review agent",
		Long: `List available agents or set the agent used for wingman reviews.

With no arguments, lists all available agents and their models.
With one argument, sets the agent (model resets to the agent's default).
With two arguments, sets both agent and model.`,
		Args: cobra.MaximumNArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return runWingmanAgentList(cmd)
			}
			model := ""
			if len(args) == 2 {
				model = args[1]
			}
			return runWingmanAgentSet(cmd, args[0], model, useLocal)
		},
	}

	cmd.Flags().BoolVar(&useLocal, "local", false, "Write to settings.local.json instead of settings.json")

	return cmd
}

func runWingmanAgentList(cmd *cobra.Command) error {
	s, err := settings.Load()
	if err != nil {
		return fmt.Errorf("failed to load settings: %w", err)
	}

	currentDef, currentModel := resolveWingmanAgent(s)

	fmt.Fprintln(cmd.OutOrStdout(), "Available wingman agents:")
	fmt.Fprintln(cmd.OutOrStdout())
	for _, def := range wingmanAgents {
		marker := "  "
		if def.Name == currentDef.Name {
			marker = "* "
		}
		fmt.Fprintf(cmd.OutOrStdout(), "%s%s\n", marker, def.Name)
		fmt.Fprintf(cmd.OutOrStdout(), "    Binary: %s\n", def.Binary)
		models := make([]string, len(def.Models))
		copy(models, def.Models)
		for i, m := range models {
			if m == def.DefaultModel {
				models[i] = m + " (default)"
			}
		}
		fmt.Fprintf(cmd.OutOrStdout(), "    Models: %s\n", strings.Join(models, ", "))
	}
	fmt.Fprintln(cmd.OutOrStdout())
	fmt.Fprintf(cmd.OutOrStdout(), "Current: %s %s\n", currentDef.Name, currentModel)
	return nil
}

func runWingmanAgentSet(cmd *cobra.Command, agentName, model string, useLocal bool) error {
	def := getWingmanAgentDef(agentName)
	if def == nil {
		names := make([]string, len(wingmanAgents))
		for i, a := range wingmanAgents {
			names[i] = a.Name
		}
		return fmt.Errorf("unknown agent %q (available: %s)", agentName, strings.Join(names, ", "))
	}

	if model == "" {
		model = def.DefaultModel
	} else if !isValidWingmanModel(def, model) {
		return fmt.Errorf("unknown model %q for agent %s (available: %s)", model, def.Name, strings.Join(def.Models, ", "))
	}

	s, err := loadSettingsTarget(useLocal)
	if err != nil {
		return fmt.Errorf("failed to load settings: %w", err)
	}

	updateWingmanOpts(s, map[string]any{"agent": agentName, "model": model})

	if err := saveSettingsTarget(s, useLocal); err != nil {
		return fmt.Errorf("failed to save settings: %w", err)
	}

