// callAgentForReview calls the configured agent CLI to perform the review.
// repoRoot is the repository root so the reviewer can access the full codebase.
func callAgentForReview(repoRoot, prompt string, agentDef *WingmanAgentDef, model string) (string, error) {
	ctx, cancel := context.WithTimeout(context.Background(), wingmanReviewTimeout)
	defer cancel()

	args := agentDef.BuildReviewArgs(model)
	cmd := exec.CommandContext(ctx, agentDef.Binary, args...) //nolint:gosec // binary/args from internal registry

	// Run from repo root so the reviewer can read source files for context.
	// Loop-breaking is handled by --setting-sources "" (disables hooks) and
	// wingmanStripGitEnv (prevents git index pollution).
	cmd.Dir = repoRoot
	cmd.Env = wingmanStripGitEnv(os.Environ())

	cmd.Stdin = strings.NewReader(prompt)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		var execErr *exec.Error
		if errors.As(err, &execErr) {
			return "", fmt.Errorf("%s CLI not found: %w", agentDef.Binary, err)
		}
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			return "", fmt.Errorf("%s CLI failed (exit %d): %s", agentDef.Binary, exitErr.ExitCode(), stderr.String())
		}
		return "", fmt.Errorf("failed to run %s CLI: %w", agentDef.Binary, err)
	}

	// For claude-code, parse JSON response; for others, use raw stdout
	if agentDef.Name == "claude-code" {
		var cliResponse wingmanCLIResponse
		if err := json.Unmarshal(stdout.Bytes(), &cliResponse); err != nil {
			return "", fmt.Errorf("failed to parse %s CLI response: %w", agentDef.Binary, err)
		}
		return cliResponse.Result, nil
	}

	return stdout.String(), nil
}

