	"github.com/entireio/cli/cmd/entire/cli/settings"
)

const (
	testAgentCodex  = "codex"
	testModelO3Mini = "o3-mini"
	testModelO3     = "o3"
)

func TestGetWingmanAgentDef_Known(t *testing.T) {
	t.Parallel()

	for _, name := range []string{"claude-code", testAgentCodex, "gemini-cli"} {
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			def := getWingmanAgentDef(name)
			if def == nil {
				t.Fatalf("expected non-nil def for %q", name)
			}
			if def.Name != name {
				t.Errorf("Name = %q, want %q", def.Name, name)
			}
			if def.Binary == "" {
				t.Error("Binary should not be empty")
			}
			if len(def.Models) == 0 {
				t.Error("Models should not be empty")
			}
			if def.DefaultModel == "" {
				t.Error("DefaultModel should not be empty")
			}
			if def.BuildReviewArgs == nil {
				t.Error("BuildReviewArgs should not be nil")
			}
			if def.BuildApplyArgs == nil {
				t.Error("BuildApplyArgs should not be nil")
			}
		})
	}
}

func TestGetWingmanAgentDef_Unknown(t *testing.T) {
	t.Parallel()

	def := getWingmanAgentDef("nonexistent")
	if def != nil {
		t.Errorf("expected nil for unknown agent, got %+v", def)
	}
}

func TestIsValidWingmanModel(t *testing.T) {
	t.Parallel()

	def := getWingmanAgentDef("claude-code")
	if def == nil {
		t.Fatal("claude-code agent not found")
	}

	tests := []struct {
		model string
		valid bool
	}{
		{"haiku", true},
		{"sonnet", true},
		{"opus", true},
		{"gpt-4", false},
		{"", false},
	}

	for _, tt := range tests {
		t.Run(tt.model, func(t *testing.T) {
			t.Parallel()
			got := isValidWingmanModel(def, tt.model)
			if got != tt.valid {
				t.Errorf("isValidWingmanModel(%q) = %v, want %v", tt.model, got, tt.valid)
			}
		})
	}
}

func TestResolveWingmanAgent_Defaults(t *testing.T) {
	t.Parallel()

	s := &settings.EntireSettings{}
	def, model := resolveWingmanAgent(s)

	if def.Name != defaultWingmanAgentName {
		t.Errorf("default agent = %q, want %q", def.Name, defaultWingmanAgentName)
	}
	if model != wingmanReviewModel {
		t.Errorf("default model = %q, want %q", model, wingmanReviewModel)
	}
}

func TestResolveWingmanAgent_FromSettings(t *testing.T) {
	t.Parallel()

	s := &settings.EntireSettings{
		StrategyOptions: map[string]any{
			"wingman": map[string]any{
				"agent": testAgentCodex,
				"model": testModelO3Mini,
			},
		},
