	def, model := resolveWingmanAgent(s)

	if def.Name != testAgentCodex {
		t.Errorf("agent = %q, want %q", def.Name, testAgentCodex)
	}
	if model != testModelO3Mini {
		t.Errorf("model = %q, want %q", model, testModelO3Mini)
	}
}

func TestResolveWingmanAgent_UnknownAgentFallsBack(t *testing.T) {
	t.Parallel()

	s := &settings.EntireSettings{
		StrategyOptions: map[string]any{
			"wingman": map[string]any{
				"agent": "unknown-agent",
			},
		},
	}
	def, model := resolveWingmanAgent(s)

	if def.Name != defaultWingmanAgentName {
		t.Errorf("should fall back to %s, got %q", defaultWingmanAgentName, def.Name)
