				"agent": testAgentCodex,
				"model": "invalid-model",
			},
		},
	}
	def, model := resolveWingmanAgent(s)

	if def.Name != testAgentCodex {
		t.Errorf("agent = %q, want %q", def.Name, testAgentCodex)
	}
	if model != testModelO3 {
		t.Errorf("should fall back to default model, got %q", model)
	}
}

func TestWingmanAgentList_Output(t *testing.T) {
	// Uses t.Chdir so cannot be parallel
	tmpDir := t.TempDir()

	cmd := exec.CommandContext(context.Background(), "git", "init", tmpDir)
	if err := cmd.Run(); err != nil {
		t.Fatalf("failed to git init: %v", err)
	}

	entireDir := filepath.Join(tmpDir, ".entire")
	if err := os.MkdirAll(entireDir, 0o755); err != nil {
		t.Fatal(err)
	}

	if err := os.WriteFile(filepath.Join(entireDir, "settings.json"), []byte(testSettingsEnabled), 0o644); err != nil {
		t.Fatal(err)
	}

	t.Chdir(tmpDir)

	agentCmd := newWingmanAgentCmd()
	var buf bytes.Buffer
	agentCmd.SetOut(&buf)
	agentCmd.SetArgs([]string{})

	if err := agentCmd.Execute(); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	output := buf.String()
	if !strings.Contains(output, "claude-code") {
		t.Error("output should contain claude-code")
	}
	if !strings.Contains(output, testAgentCodex) {
		t.Error("output should contain codex")
	}
	if !strings.Contains(output, "gemini-cli") {
		t.Error("output should contain gemini-cli")
	}
	if !strings.Contains(output, "Current:") {
		t.Error("output should contain Current footer")
	}
}

func TestWingmanAgentSet_InvalidAgent(t *testing.T) {
	t.Parallel()

	agentCmd := newWingmanAgentCmd()
	agentCmd.SetArgs([]string{"nonexistent"})
	agentCmd.SetOut(&bytes.Buffer{})

	err := agentCmd.Execute()
	if err == nil {
		t.Fatal("expected error for invalid agent")
	}
	if !strings.Contains(err.Error(), "unknown agent") {
		t.Errorf("error should mention unknown agent, got: %v", err)
	}
}

