	t.Parallel()

	agentCmd := newWingmanAgentCmd()
	agentCmd.SetArgs([]string{"claude-code", "gpt-4"})
	agentCmd.SetOut(&bytes.Buffer{})

	err := agentCmd.Execute()
	if err == nil {
		t.Fatal("expected error for invalid model")
	}
	if !strings.Contains(err.Error(), "unknown model") {
		t.Errorf("error should mention unknown model, got: %v", err)
	}
}

func TestWingmanAgentSet_Success(t *testing.T) {
	// Uses t.Chdir so cannot be parallel
	tmpDir := t.TempDir()

	cmd := exec.CommandContext(context.Background(), "git", "init", tmpDir)
	if err := cmd.Run(); err != nil {
		t.Fatalf("failed to git init: %v", err)
	}

	entireDir := filepath.Join(tmpDir, ".entire")
	if err := os.MkdirAll(entireDir, 0o755); err != nil {
		t.Fatal(err)
	}

	if err := os.WriteFile(filepath.Join(entireDir, "settings.json"), []byte(testSettingsEnabled), 0o644); err != nil {
		t.Fatal(err)
	}

	t.Chdir(tmpDir)

	agentCmd := newWingmanAgentCmd()
	var buf bytes.Buffer
	agentCmd.SetOut(&buf)
	agentCmd.SetArgs([]string{testAgentCodex, testModelO3Mini})

	if err := agentCmd.Execute(); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	output := buf.String()
	if !strings.Contains(output, testAgentCodex) {
		t.Error("output should confirm codex agent")
	}
	if !strings.Contains(output, testModelO3Mini) {
		t.Error("output should confirm o3-mini model")
	}

	// Verify settings file
	s, err := settings.Load()
	if err != nil {
		t.Fatalf("failed to load settings: %v", err)
	}
	if s.GetWingmanAgent() != testAgentCodex {
		t.Errorf("agent in settings = %q, want %q", s.GetWingmanAgent(), testAgentCodex)
	}
	if s.GetWingmanModel() != testModelO3Mini {
		t.Errorf("model in settings = %q, want %q", s.GetWingmanModel(), testModelO3Mini)
	}
}

func TestUpdateWingmanOpts_PreservesExisting(t *testing.T) {
	t.Parallel()

	s := &settings.EntireSettings{
		StrategyOptions: map[string]any{
			"wingman": map[string]any{
				"agent":   testAgentCodex,
				"model":   testModelO3,
				"enabled": true,
			},
		},
	}

	// Update only enabled, agent/model should be preserved
	updateWingmanOpts(s, map[string]any{"enabled": false})

	wingmanOpts, ok := s.StrategyOptions["wingman"].(map[string]any)
	if !ok {
		t.Fatal("wingman options should exist")
	}

	if wingmanOpts["agent"] != testAgentCodex {
		t.Errorf("agent should be preserved, got %v", wingmanOpts["agent"])
	}
	if wingmanOpts["model"] != testModelO3 {
		t.Errorf("model should be preserved, got %v", wingmanOpts["model"])
	}
	if wingmanOpts["enabled"] != false {
		t.Errorf("enabled should be updated to false, got %v", wingmanOpts["enabled"])
	}
}

func TestUpdateWingmanOpts_NilStrategyOptions(t *testing.T) {
	t.Parallel()

	s := &settings.EntireSettings{}
	updateWingmanOpts(s, map[string]any{"enabled": true})

	wingmanOpts, ok := s.StrategyOptions["wingman"].(map[string]any)
	if !ok {
		t.Fatal("wingman options should exist")
	}
	if wingmanOpts["enabled"] != true {
		t.Errorf("enabled should be true, got %v", wingmanOpts["enabled"])
	}
}

func TestBuildReviewArgs_ClaudeCode(t *testing.T) {
	t.Parallel()

	def := getWingmanAgentDef("claude-code")
	if def == nil {
		t.Fatal("claude-code agent not found")
	}

	args := def.BuildReviewArgs("opus")
	found := false
	for i, a := range args {
		if a == "--model" && i+1 < len(args) && args[i+1] == "opus" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("BuildReviewArgs should include --model opus, got %v", args)
	}
}

func TestBuildApplyArgs_ClaudeCode(t *testing.T) {
	t.Parallel()

	def := getWingmanAgentDef("claude-code")
	if def == nil {
		t.Fatal("claude-code agent not found")
	}

	args := def.BuildApplyArgs()
	foundContinue := false
	for _, a := range args {
		if a == "--continue" {
			foundContinue = true
			break
		}
	}
	if !foundContinue {
		t.Errorf("BuildApplyArgs should include --continue, got %v", args)
	}
}

